import React, { useState } from 'react';
import { Sparkles, FileText, Target, Lightbulb, Copy, X, RefreshCw } from 'lucide-react';
import toast from 'react-hot-toast';
import geminiService from '../services/geminiService';

export default function NoteSummary({ title, content, isVisible, onClose }) {
  const [summary, setSummary] = useState('');
  const [insights, setInsights] = useState('');
  const [actionItems, setActionItems] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('summary');
  const [hasGenerated, setHasGenerated] = useState(false);

  const generateContent = async (type = 'all') => {
    if (!content || content.trim().length === 0) {
      toast.error('No content available to summarize');
      return;
    }

    setIsLoading(true);
    try {
      if (type === 'all' || type === 'summary') {
        const summaryResult = await geminiService.generateSummary(content, title);
        setSummary(summaryResult);
      }
      
      if (type === 'all' || type === 'insights') {
        const insightsResult = await geminiService.generateInsights(content, title);
        setInsights(insightsResult);
      }
      
      if (type === 'all' || type === 'actionItems') {
        const actionItemsResult = await geminiService.generateActionItems(content, title);
        setActionItems(actionItemsResult);
      }

      setHasGenerated(true);
      toast.success('AI analysis completed!');
    } catch (error) {
      console.error('Error generating content:', error);
      toast.error(error.message || 'Failed to generate AI analysis');
    } finally {
      setIsLoading(false);
    }
  };

  const copyToClipboard = async (text, type) => {
    try {
      await navigator.clipboard.writeText(text);
      toast.success(`${type} copied to clipboard!`);
    } catch (error) {
      toast.error('Failed to copy to clipboard');
    }
  };

  const regenerateContent = async () => {
    setSummary('');
    setInsights('');
    setActionItems('');
    setHasGenerated(false);
    await generateContent('all');
  };

  if (!isVisible) return null;

  const tabs = [
    { id: 'summary', label: 'Summary', icon: FileText, content: summary },
    { id: 'insights', label: 'Insights', icon: Lightbulb, content: insights },
    { id: 'actionItems', label: 'Action Items', icon: Target, content: actionItems }
  ];

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      right: 0,
      width: '400px',
      height: '100vh',
      background: 'white',
      boxShadow: '-4px 0 20px rgba(0, 0, 0, 0.1)',
      zIndex: 1000,
      display: 'flex',
      flexDirection: 'column',
      borderLeft: '1px solid #e5e7eb'
    }}>
      {/* Header */}
      <div style={{
        padding: '20px',
        borderBottom: '1px solid #e5e7eb',
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        color: 'white'
      }}>
        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: '8px'
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Sparkles size={20} />
            <h3 style={{ margin: 0, fontSize: '18px', fontWeight: '600' }}>
              AI Analysis
            </h3>
          </div>
          <button
            onClick={onClose}
            style={{
              background: 'rgba(255, 255, 255, 0.2)',
              border: 'none',
              borderRadius: '6px',
              padding: '6px',
              cursor: 'pointer',
              color: 'white',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}
          >
            <X size={16} />
          </button>
        </div>
        <p style={{ 
          margin: 0, 
          fontSize: '14px', 
          opacity: 0.9,
          fontWeight: '400'
        }}>
          Get AI-powered insights from your notes
        </p>
      </div>

      {/* Action Buttons */}
      <div style={{
        padding: '16px',
        borderBottom: '1px solid #f1f5f9',
        background: '#fafbfc'
      }}>
        <div style={{ display: 'flex', gap: '8px' }}>
          {!hasGenerated ? (
            <button
              onClick={() => generateContent('all')}
              disabled={isLoading}
              style={{
                flex: 1,
                padding: '10px 16px',
                background: isLoading ? '#f3f4f6' : '#10b981',
                color: isLoading ? '#9ca3af' : 'white',
                border: 'none',
                borderRadius: '8px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px',
                transition: 'all 0.2s ease'
              }}
            >
              {isLoading ? (
                <>
                  <div className="spinner" style={{ width: '16px', height: '16px' }} />
                  Analyzing...
                </>
              ) : (
                <>
                  <Sparkles size={16} />
                  Generate Analysis
                </>
              )}
            </button>
          ) : (
            <button
              onClick={regenerateContent}
              disabled={isLoading}
              style={{
                flex: 1,
                padding: '10px 16px',
                background: isLoading ? '#f3f4f6' : '#6366f1',
                color: isLoading ? '#9ca3af' : 'white',
                border: 'none',
                borderRadius: '8px',
                fontSize: '14px',
                fontWeight: '500',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px',
                transition: 'all 0.2s ease'
              }}
            >
              {isLoading ? (
                <>
                  <div className="spinner" style={{ width: '16px', height: '16px' }} />
                  Regenerating...
                </>
              ) : (
                <>
                  <RefreshCw size={16} />
                  Regenerate
                </>
              )}
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      {hasGenerated && (
        <div style={{
          display: 'flex',
          borderBottom: '1px solid #e5e7eb',
          background: '#f8fafc'
        }}>
          {tabs.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                style={{
                  flex: 1,
                  padding: '12px 8px',
                  background: activeTab === tab.id ? 'white' : 'transparent',
                  border: 'none',
                  borderBottom: activeTab === tab.id ? '2px solid #6366f1' : '2px solid transparent',
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '6px',
                  fontSize: '12px',
                  fontWeight: '500',
                  color: activeTab === tab.id ? '#6366f1' : '#6b7280',
                  transition: 'all 0.2s ease'
                }}
              >
                <Icon size={14} />
                {tab.label}
              </button>
            );
          })}
        </div>
      )}

      {/* Content */}
      <div style={{ flex: 1, overflow: 'auto' }}>
        {!hasGenerated ? (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            height: '100%',
            textAlign: 'center',
            padding: '40px 20px'
          }}>
            <div>
              <Sparkles size={48} style={{ color: '#d1d5db', marginBottom: '16px' }} />
              <h4 style={{ 
                margin: '0 0 8px 0', 
                color: '#374151',
                fontSize: '16px',
                fontWeight: '600'
              }}>
                Ready to Analyze
              </h4>
              <p style={{ 
                margin: 0, 
                color: '#6b7280',
                fontSize: '14px',
                lineHeight: '1.5'
              }}>
                Click "Generate Analysis" to get AI-powered insights, summaries, and action items from your note.
              </p>
            </div>
          </div>
        ) : (
          <div style={{ padding: '20px' }}>
            {tabs.map((tab) => {
              if (activeTab !== tab.id) return null;
              
              return (
                <div key={tab.id}>
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    marginBottom: '16px'
                  }}>
                    <h4 style={{
                      margin: 0,
                      fontSize: '16px',
                      fontWeight: '600',
                      color: '#374151',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '8px'
                    }}>
                      <tab.icon size={18} />
                      {tab.label}
                    </h4>
                    {tab.content && (
                      <button
                        onClick={() => copyToClipboard(tab.content, tab.label)}
                        style={{
                          padding: '6px 8px',
                          background: 'transparent',
                          border: '1px solid #e5e7eb',
                          borderRadius: '6px',
                          cursor: 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '4px',
                          fontSize: '12px',
                          color: '#6b7280',
                          transition: 'all 0.2s ease'
                        }}
                        title="Copy to clipboard"
                      >
                        <Copy size={12} />
                        Copy
                      </button>
                    )}
                  </div>
                  
                  {tab.content ? (
                    <div style={{
                      background: '#f8fafc',
                      border: '1px solid #e5e7eb',
                      borderRadius: '8px',
                      padding: '16px',
                      fontSize: '14px',
                      lineHeight: '1.6',
                      color: '#374151',
                      whiteSpace: 'pre-wrap'
                    }}>
                      {tab.content}
                    </div>
                  ) : (
                    <div style={{
                      background: '#f8fafc',
                      border: '1px solid #e5e7eb',
                      borderRadius: '8px',
                      padding: '16px',
                      textAlign: 'center',
                      color: '#6b7280',
                      fontSize: '14px'
                    }}>
                      <div className="spinner" style={{ 
                        width: '20px', 
                        height: '20px', 
                        margin: '0 auto 8px' 
                      }} />
                      Generating {tab.label.toLowerCase()}...
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
