import { GoogleGenerativeAI } from '@google/generative-ai';
import { firebaseAIConfig, auth } from '../firebase';

// Initialize the Gemini API with Firebase integration
const genAI = new GoogleGenerativeAI(firebaseAIConfig.geminiApiKey);

class GeminiService {
  constructor() {
    // Use the stable model name that works with the current API
    this.model = genAI.getGenerativeModel({ model: 'models/gemini-1.5-flash' });
  }

  /**
   * Check if user is authenticated with Firebase
   * @returns {boolean} - True if user is authenticated
   */
  isUserAuthenticated() {
    return auth.currentUser !== null;
  }

  /**
   * Generate a summary of the given text content
   * @param {string} content - The text content to summarize
   * @param {string} title - The title of the note (optional)
   * @returns {Promise<string>} - The generated summary
   */
  async generateSummary(content, title = '') {
    try {
      // Check Firebase authentication
      if (!this.isUserAuthenticated()) {
        throw new Error('User must be authenticated to use AI features');
      }

      if (!content || content.trim().length === 0) {
        throw new Error('Content is required for summary generation');
      }

      // Create a prompt for summarization
      const prompt = `Please provide a concise and informative summary of the following note${title ? ` titled "${title}"` : ''}:

Content:
${content}

Instructions:
- Create a clear, concise summary that captures the main points
- Use bullet points if the content has multiple key topics
- Keep the summary between 2-4 sentences or bullet points
- Focus on the most important information
- Make it easy to understand at a glance

Summary:`;

      const result = await this.model.generateContent(prompt);
      const response = await result.response;
      const summary = response.text();

      if (!summary || summary.trim().length === 0) {
        throw new Error('Failed to generate summary - empty response');
      }

      return summary.trim();
    } catch (error) {
      console.error('Error generating summary:', error);
      throw new Error(`Failed to generate summary: ${error.message}`);
    }
  }

  /**
   * Generate key insights from the note content
   * @param {string} content - The text content to analyze
   * @param {string} title - The title of the note (optional)
   * @returns {Promise<string>} - The generated insights
   */
  async generateInsights(content, title = '') {
    try {
      // Check Firebase authentication
      if (!this.isUserAuthenticated()) {
        throw new Error('User must be authenticated to use AI features');
      }

      if (!content || content.trim().length === 0) {
        throw new Error('Content is required for insights generation');
      }

      const prompt = `Analyze the following note${title ? ` titled "${title}"` : ''} and provide key insights:

Content:
${content}

Instructions:
- Identify the main themes and topics
- Highlight any important conclusions or decisions
- Note any action items or next steps mentioned
- Identify any patterns or connections
- Keep insights concise and actionable

Key Insights:`;

      const result = await this.model.generateContent(prompt);
      const response = await result.response;
      const insights = response.text();

      if (!insights || insights.trim().length === 0) {
        throw new Error('Failed to generate insights - empty response');
      }

      return insights.trim();
    } catch (error) {
      console.error('Error generating insights:', error);
      throw new Error(`Failed to generate insights: ${error.message}`);
    }
  }

  /**
   * Generate action items from the note content
   * @param {string} content - The text content to analyze
   * @param {string} title - The title of the note (optional)
   * @returns {Promise<string>} - The generated action items
   */
  async generateActionItems(content, title = '') {
    try {
      // Check Firebase authentication
      if (!this.isUserAuthenticated()) {
        throw new Error('User must be authenticated to use AI features');
      }

      if (!content || content.trim().length === 0) {
        throw new Error('Content is required for action items generation');
      }

      const prompt = `Extract and organize action items from the following note${title ? ` titled "${title}"` : ''}:

Content:
${content}

Instructions:
- Identify any tasks, to-dos, or action items mentioned
- Create a clear, actionable list
- Include deadlines or timeframes if mentioned
- Prioritize items if possible (high, medium, low)
- If no explicit action items exist, suggest relevant next steps based on the content

Action Items:`;

      const result = await this.model.generateContent(prompt);
      const response = await result.response;
      const actionItems = response.text();

      if (!actionItems || actionItems.trim().length === 0) {
        throw new Error('Failed to generate action items - empty response');
      }

      return actionItems.trim();
    } catch (error) {
      console.error('Error generating action items:', error);
      throw new Error(`Failed to generate action items: ${error.message}`);
    }
  }

  /**
   * Check if the API key is configured
   * @returns {boolean} - True if API key is available
   */
  isConfigured() {
    return !!API_KEY && API_KEY !== 'your-api-key-here';
  }
}

// Export a singleton instance
export default new GeminiService();
